// Validates the document and splits it into chunks by section (## headings).
// Each chunk carries "Title > Section" so it still makes sense on its own when retrieved.
const req = $input.first().json;
const headers = req.headers || {};
const body = req.body || {};
const errors = [];
let status_code = 200;
if (!$env.WEBHOOK_TOKEN || headers['x-webhook-token'] !== $env.WEBHOOK_TOKEN) {
  status_code = 401;
  errors.push('Missing or invalid X-Webhook-Token header');
}
const doc = {
  source: typeof body.source === 'string' ? body.source.trim() : '',
  title: typeof body.title === 'string' ? body.title.trim() : '',
  content: typeof body.content === 'string' ? body.content.replace(/\r\n/g, '\n').trim() : '',
};
if (status_code === 200) {
  if (!doc.source) errors.push('source is required (a stable id such as a file name or URL)');
  if (!doc.title) errors.push('title is required');
  if (doc.content.length < 50) errors.push('content must be at least 50 characters');
  if (doc.content.length > 200000) errors.push('content exceeds 200,000 characters');
  if (errors.length) status_code = 400;
}

const MAX = 1500;
const chunks = [];
if (!errors.length) {
  const sections = [];
  let current = { heading: 'Overview', lines: [] };
  for (const line of doc.content.split('\n')) {
    if (/^#\s/.test(line)) continue;                       // document title, already known
    const h = line.match(/^#{2,3}\s+(.*)/);
    if (h) {
      if (current.lines.join('').trim()) sections.push(current);
      current = { heading: h[1].trim(), lines: [] };
    } else current.lines.push(line);
  }
  if (current.lines.join('').trim()) sections.push(current);

  for (const s of sections) {
    // long sections are split on paragraph boundaries
    let buf = '';
    for (const para of s.lines.join('\n').trim().split(/\n{2,}/)) {
      if (buf && (buf + '\n\n' + para).length > MAX) { chunks.push({ heading: s.heading, body: buf }); buf = para; }
      else buf = buf ? buf + '\n\n' + para : para;
    }
    if (buf) chunks.push({ heading: s.heading, body: buf });
  }
}

const request_id = globalThis.crypto?.randomUUID?.() ??
  'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
  });

return [{
  json: {
    ok: errors.length === 0, status_code, errors, request_id, received_at_ms: Date.now(), doc,
    chunks: chunks.map((c, i) => ({ chunk_index: i, heading: c.heading, content: `${doc.title} > ${c.heading}\n\n${c.body}` })),
  },
}];

// Pairs every chunk with its embedding, ready for a single SQL statement.
const v = $('Validate & Chunk').first().json;
const res = $input.first().json;
const vectors = (res.data || []).sort((a, b) => a.index - b.index).map((d) => d.embedding);
if (vectors.length !== v.chunks.length) throw new Error(`Expected ${v.chunks.length} embeddings, got ${vectors.length}`);
const rows = v.chunks.map((c, i) => ({ ...c, embedding: JSON.stringify(vectors[i]) }));
return [{ json: { rows: JSON.stringify(rows), chunk_count: rows.length, tokens: res.usage?.total_tokens ?? null,
                  sha: $('Check Document Version').first().json.incoming_sha } }];
